<script setup lang="ts">import {ref,computed} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import ProfileMatrix from '../components/ProfileMatrix.vue';import {catalogApi} from '../api/catalog';import {useTask} from '../hooks/useTask';const p=defineProps<{studies:any[];traces:any[];profiles:any[];user:any;reloadCatalog:()=>Promise<void>}>(),id=ref(0),raw=ref(JSON.stringify({name:'三步观测手算研究',filename:'yx-three-token-fixture.json',description:'固定二态三观测码的独立手算校验',symbols:['0','1','2'],traces:[{reference:'HAND-001',tokens:['0','1','2']}]},null,2)),task=useTask(),study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id))),rows=computed(()=>p.traces.filter(t=>t.study_id===study.value?.id)),models=computed(()=>p.profiles.filter(m=>m.study_id===study.value?.id));async function create(){await task.act(async()=>{const s=await catalogApi.createStudy(JSON.parse(raw.value));await p.reloadCatalog();id.value=s.id},'观测研究已保存，可冻结固定模型')}function revise(t:any){const text=prompt('按空格输入观测码',t.tokens.join(' '));if(text!==null)task.act(async()=>{await catalogApi.editTrace(t.id,text.trim().split(/\s+/));await p.reloadCatalog()},'轨迹已修订，既有任务保留提交时快照')}</script><template><PageTitle index="02" title="先核对观测码，再核对模型版本。" description="字母表固定；相同模型标签不等于设备真实工况。"/><label>来源研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="study">{{study.filename}} / {{study.description}} / 观测码{{study.symbols.join(' / ')}}</p><div class="source-layout"><section><h2>观测底稿 / 前20条</h2><Table :headers="['轨迹编号','码数','观测片段','修订']"><tr v-for="t in rows.slice(0,20)" :key="t.id"><td>{{t.reference}}</td><td>{{t.tokens.length}}</td><td class="tokens">{{t.tokens.slice(0,24).join(' ')}}{{t.tokens.length>24?' …':''}}</td><td><button v-if="user.role!=='viewer'" @click="revise(t)">修订</button></td></tr></Table></section><section class="input-panel"><small>NEW OBSERVATION STUDY</small><h2>导入已编码轨迹</h2><p>声明2–6观测码；每研究1–240条，每条1–200码。推断任务另限最多30条。</p><form v-if="user.role!=='viewer'" @submit.prevent="create"><label>观测 JSON<textarea v-model="raw" rows="17"/></label><button class="primary" :disabled="task.state.busy">保存观测研究 →</button></form><p v-else>观察员只读底稿。</p><Notice v-bind="task.state"/></section></div><ProfileMatrix v-for="model in models" :key="model.id" :profile="model"/></template>
